with flattened as (select c.id, c.customer_id, c.created_at, pos + 1 as line_no, entry.product_id, entry.qty, entry.price, entry.promo from carts c lateral view outer posexplode(c.items) li as pos, entry) select *, round(qty / sum(qty) over (partition by customer_id, promo), 4) as qty_share, max(product_id) over (partition by promo order by cast(created_at as bigint) range between 1800 preceding and current row) as product_id_max_30m from flattened
